package subscription

import (
	"log"
	"net"
	"sort"

	"corefusion/internal/store/repository"
)

// GeoIPResolver resolves an IP address to a country code.
type GeoIPResolver interface {
	LookupCountry(ip string) (countryCode string, err error)
}

// RegionSelector recommends the best region for a user based on GeoIP.
type RegionSelector struct {
	geoIPResolver GeoIPResolver
	serverRepo    *repository.NodeServerRepository
}

// NewRegionSelector creates a new RegionSelector.
func NewRegionSelector(resolver GeoIPResolver, serverRepo *repository.NodeServerRepository) *RegionSelector {
	return &RegionSelector{
		geoIPResolver: resolver,
		serverRepo:    serverRepo,
	}
}

// regionProximity maps each server region to a list of nearby countries (ISO 3166-1 alpha-2).
var regionProximity = map[string][]string{
	"HK": {"CN", "HK", "TW", "MO", "VN", "TH"},
	"JP": {"JP", "KR", "CN"},
	"US": {"US", "CA", "MX"},
	"SG": {"SG", "MY", "ID", "TH", "VN"},
	"EU": {"GB", "DE", "FR", "NL", "LU", "SE", "NO", "FI"},
	"KR": {"KR", "JP", "CN"},
	"DE": {"DE", "NL", "FR", "BE", "AT", "CH"},
	"GB": {"GB", "IE", "FR", "NL", "BE"},
	"TR": {"TR", "BG", "GR", "RO"},
	"AU": {"AU", "NZ", "ID", "SG"},
}

// RecommendRegion recommends the best region for a user based on their IP.
// allowedRegions is the list of regions the user's plan permits.
// Returns the first allowed region if no match is found.
func (s *RegionSelector) RecommendRegion(clientIP string, allowedRegions []string) string {
	if len(allowedRegions) == 0 {
		return ""
	}
	if len(allowedRegions) == 1 {
		return allowedRegions[0]
	}

	if clientIP == "" {
		return allowedRegions[0]
	}

	// Parse IP
	ip := net.ParseIP(clientIP)
	if ip == nil {
		return allowedRegions[0]
	}

	// Lookup country
	userCountry, err := s.geoIPResolver.LookupCountry(clientIP)
	if err != nil || userCountry == "" {
		log.Printf("[RegionSelector] GeoIP lookup failed for %s: %v", clientIP, err)
		return allowedRegions[0]
	}

	// Sort allowed regions by proximity score
	scored := make([]regionScore, 0, len(allowedRegions))
	for _, region := range allowedRegions {
		score := 0
		countries := regionProximity[region]
		for i, c := range countries {
			if c == userCountry {
				score = len(countries) - i // higher score for earlier match
				break
			}
		}
		scored = append(scored, regionScore{region: region, score: score})
	}

	sort.Slice(scored, func(i, j int) bool {
		return scored[i].score > scored[j].score
	})

	// If best score is 0, fall back to first allowed
	if scored[0].score == 0 {
		return allowedRegions[0]
	}

	return scored[0].region
}

// RecommendServers returns server IDs in the recommended region.
func (s *RegionSelector) RecommendServers(clientIP string, allowedRegions []string) ([]int64, error) {
	region := s.RecommendRegion(clientIP, allowedRegions)
	if region == "" {
		return nil, nil
	}

	servers, err := s.serverRepo.ListByRegion(nil, region)
	if err != nil {
		return nil, err
	}

	var ids []int64
	for _, s := range servers {
		ids = append(ids, s.ID)
	}
	return ids, nil
}

// regionScore holds a region and its proximity score.
type regionScore struct {
	region string
	score  int
}

// NoopGeoIPResolver is a stub GeoIPResolver that always returns empty.
// Used when GeoIP is not configured.
type NoopGeoIPResolver struct{}

// LookupCountry returns an empty country code (no-op).
func (n *NoopGeoIPResolver) LookupCountry(ip string) (string, error) {
	return "", nil
}

