// LookupCountry resolves an IP address to a country code.
func (r *SimpleGeoIPResolver) LookupCountry(ipStr string) (string, error) {
	ip := net.ParseIP(ipStr)
	if ip == nil {
		return "", nil
	}

	for country, prefixes := range r.countryPrefixes {
		for _, prefix := range prefixes {
			_, network, err := net.ParseCIDR(prefix)
			if err != nil {
				continue
			}
			if network.Contains(ip) {
				return country, nil
			}
		}
	}

	return "", nil
}
